\label{lem:Haagerup_approx_groups}
    Let $Y$ be a Banach space and let $(V_s)_{s\in\mathbb R}$ be a point-weak$^\ast$ continuous group on $Y^\ast$. If $x\in Y^\ast$, then for every $n\in\mathbb N$ the weak$^\ast$ integral
    \begin{equation*}
        x_n=\sqrt\frac n \pi\int_\mathbb R e^{-ns^2}V_s x\,ds
    \end{equation*}
    exists, belongs to $\bigcap_{z\in\mathbb C}\operatorname{dom}(V_z)$, satisfies
    \begin{equation*}
        V_zx_n=\sqrt\frac n\pi \int_\mathbb R e^{-n(s-z)^2 }V_sx\,ds
    \end{equation*}
    for all $z\in\mathbb C$ and $x_n\to x$ in weak$^\ast$ topology as $n\to\infty$. Moreover, if $x\in \operatorname{dom}(V_z)$, then 
    \begin{equation*}
        V_z x_n=\sqrt\frac n \pi\int_\mathbb R e^{-ns^2}V_{s+z} x\,ds.
    \end{equation*}

Let $x\in \operatorname{dom}(V_z)$ and let $(x_k)$ be a sequence in $D$ such that $x_k\to x$ in $H$. By \Cref{lem:Haagerup_approx_groups}, we have $\sqrt\frac n\pi\int_\mathbb R e^{-ns^2}V_s(x_k-x)\,ds\in \operatorname{dom}(V_z)$ and 
    \begin{equation*}
        V_z\left(\sqrt\frac n\pi\int_\mathbb R e^{-ns^2}V_s(x-x_k)\,ds\right)=\sqrt\frac n\pi\int_\mathbb R e^{-n(s-z)^2}V_s(x-x_k)\,ds.
    \end{equation*}
    Moreover, there exist $c,\omega>0$ such that $\lVertV_s\rVert\leq c e^{\omega\lverts\rvert}$ for all $s\in\mathbb R$. Thus
    \begin{align*}
        \left\lVert V_z\left(\sqrt\frac n\pi\int_\mathbb R e^{-ns^2}V_s(x_k-x)\,ds\right)\right\rVert&\leq \sqrt\frac n\pi\int_\mathbb R \lverte^{-n(s-z)^2}\rvert\lVertV_s(x-x_k)\rVert\,ds\\
        &\leq \sqrt\frac n\pi e^{n(\operatorname{Im} z)^2}\lVertx-x_k\rVert\int_\mathbb R e^{-n(s-\operatorname{Re} z)^2} c e^{\omega\lverts\rvert}\,ds.
    \end{align*}
    As $\int_\mathbb R e^{-n(s-\operatorname{Re} z)^2} c e^{\omega\lverts\rvert}\,ds<\infty$, it follows that $\left\lVert V_z\left(\sqrt\frac n\pi\int_\mathbb R e^{-ns^2}V_s(x_k-x)\,ds\right)\right\rVert\to 0$ as $k\to \infty$. Combined with the same argument for $z=0$, this implies that 
    \begin{equation*}
        \sqrt\frac n\pi\int_\mathbb R e^{-ns^2}V_s x_k\,ds\to \sqrt\frac n\pi\int_\mathbb R e^{-ns^2}V_s x\,ds
    \end{equation*}
    as $k\to\infty$ in the graph norm of $V_z$.

    Since $\sqrt\frac n\pi\int_\mathbb R e^{-ns^2}V_s x\,ds\to x$ in the graph norm of $V_z$ as a consequence of \Cref{lem:Haagerup_approx_groups}, we conclude that $x$ belongs to the closed linear span of 
    \begin{equation*}
        \left\{\sqrt\frac n\pi\int_\mathbb R e^{-ns^2}V_sy\,ds:y\in D,n\in\mathbb N\right\}
    \end{equation*}
    with respect to the graph norm.

    Moreover, as
    \begin{align*}
        \sqrt\frac n\pi\int_\mathbb R e^{-ns^2}\lVertV_s y\rVert_{V_z}\,ds&=\sqrt\frac n\pi\int_\mathbb R e^{-ns^2}(\lVertV_s y\rVert^2+\lVertV_{s+z} y\rVert^2)^{1/2}\,ds\\
        &\leq K\left(\sqrt \frac n\pi\int_\mathbb R e^{-ns^2}e^{\omega\lverts\rvert}\,ds\right)\lVerty\rVert_{V_z},
    \end{align*}
    the integral $\sqrt\frac n\pi\int_\mathbb R e^{-ns^2}V_s y\,ds$ converges absolutely in $(\operatorname{dom}(V_z),\lVert\cdot\rVert_{V_z})$. Hence it belongs to the closed linear span of $\{V_s y\mid s\in\mathbb R\}$ in $(\operatorname{dom}(V_z),\lVert\cdot\rVert_{V_z})$. Finally, since $D$ is invariant under $(V_s)_{s\in\mathbb R}$, whenever $y\in D$, then the linear span of $\{V_s y\mid s\in\mathbb R\}$ is contained in $D$. Altogether, we have proven that $x$ belongs to the closure of $D$ with respect to $\lVert\cdot\rVert_{V_z}$.

\label{lem:appl_residue_thm}
    Let $S=\{z\in\mathbb C\mid -1/4<\operatorname{Re} z<1/4\}$. If $f\colon \overline S\to\mathbb C$ is a bounded continuous function that is analytic on $S$, then
    \begin{equation*}
        f(0)=\int_{\mathbb R}(f(-1/4+it)+f(1/4+it))\frac{dt}{\cosh 2\pi t}.
    \end{equation*}

For $z\in S\setminus\{0\}$ let $g(z)=\frac{f(z)}{\sin 2\pi z}$. The function is meromorphic on $S$ with a single pole with residue $f(0)/2\pi$ at $0$. Moreover, $\lim_{R\to\infty}\lvertg(s\pm iR)\rvert=0$ uniformly in $s\in [-1/4,1/4]$.

    For $R,\varepsilon>0$ let $\gamma_{R,\varepsilon}$ be the positively oriented curve running along the boundary of $\{z\in \mathbb C:\lvert\operatorname{Re} z\rvert\leq \frac 1 4-\varepsilon,\lvert\operatorname{Im} z\rvert\leq R\}$. By the residue theorem,
    \begin{equation*}
        f(0)=-i\int_{\gamma_{R,\varepsilon}}g(z)\,dz.
    \end{equation*}
    Since $g$ is continuous on $S\setminus \{0\}$, we have
    \begin{equation*}
        \lim_{\varepsilon\to 0}\int_{\gamma_{R,\varepsilon}}g(z)\,dz=\int_{\gamma_R}g(z),dz,
    \end{equation*}
    where $\gamma_R$ is the positively oriented curve running along the boundary of $\{z\in \mathbb C:\lvert\operatorname{Re} z\rvert\leq \frac 1 4,\lvert\operatorname{Im} z\rvert\leq R\}$. Second, because $\lim_{R\to\infty}\lvertg(s\pm iR)\rvert=0$ uniformly in $s\in [-1/4,1/4]$, we can take the limit $R\to\infty$ to get
    \begin{align*}
        f(0)
        &=-i\lim_{R\to\infty}\int_{\gamma_R}g(z)\,dz\\
        &=\int_\mathbb R (g(1/4+it)-g(-1/4+it))\,dt\\
        &=\int_\mathbb R (f(-1/4+it)+f(1/4+it))\frac{dt}{\cosh 2\pi t}.\qedhere
    \end{align*}

If $T\in B(L^2(M))$ and $\xi,\eta\in L^2(M)$, then
    \begin{equation*}
        \langle \xi,\check T\eta\rangle=\int_\mathbb R \langle \Delta_\varphi^{it}\xi,T\Delta_\varphi^{it}\eta\rangle\frac{2\,dt}{\cosh 2\pi t}.
    \end{equation*}

First note that
    \begin{equation*}
        \int_\mathbb R \lvert\langle \Delta_\varphi^{it}\xi,T\Delta_\varphi^{it}\eta\rangle\rvert\frac{2\,dt}{\cosh 2\pi t}\leq \lVertT\rVert\lVert\xi\rVert\lVert\eta\rVert\int_\mathbb R\frac{2\,dt}{\cosh 2\pi t}=\lVertT\rVert\lVert\xi\rVert\lVert\eta\rVert.
    \end{equation*}
    Hence the integral converges absolutely and there exists a unique $R\in B(L^2(M))$ such that $\langle \xi,R\eta\rangle=\int_\mathbb R \langle \Delta_\varphi^{it}\xi,T\Delta_\varphi^{it}\eta\rangle\frac{2\,dt}{\cosh 2\pi t}$ for all $\xi,\eta\in L^2(M)$.

    If $\xi,\eta\in \operatorname{dom}(\Delta_\varphi^{1/4})\cap \operatorname{dom}(\Delta_\varphi^{-1/4})$, then
    \begin{align*}
        &\frac 1 2\langle \Delta_\varphi^{1/4}\xi,R \Delta_\varphi^{-1/4}\eta\rangle+\frac 1 2\langle \Delta_\varphi^{-1/4}\xi,R \Delta_\varphi^{1/4}\eta\rangle\\
        &\quad=\int_\mathbb R(\langle \Delta_\varphi^{1/4+it}\xi,T\Delta_\varphi^{-1/4+it}\eta\rangle+\langle \Delta_\varphi^{-1/4+it}\xi,T\Delta_\varphi^{1/4+it}\eta\rangle)\frac{2\,dt}{\cosh 2\pi t}.
    \end{align*}
    For $z\in \mathbb C$ with $\lvert\operatorname{Re} z\rvert\leq \frac 1 4$ let $f(z)=\langle \Delta_\varphi^{-\bar z}\xi,T\Delta_\varphi^z \eta\rangle$. By \cite[Lemma VI.2.3]{Tak03}, the function $f$ is bounded and continuous on the closed strip $\{z\in \mathbb C:\lvert\operatorname{Re} z\rvert\leq \frac 1 4\}$ and analytic on its interior. It follows from \Cref{lem:appl_residue_thm} that
    \begin{align*}
        \int_\mathbb R(\langle \Delta_\varphi^{1/4+it}\xi,T\Delta_\varphi^{-1/4+it}\eta\rangle+\langle \Delta_\varphi^{-1/4+it}\xi,T\Delta_\varphi^{1/4+it}\eta\rangle)\frac{2\,dt}{\cosh 2\pi t}=f(0)=\langle \xi,T\eta\rangle.
    \end{align*}
    Therefore, $R=\check T$ by \cite[Lemma 3.4]{VW23}.

\label{thm:int_rep_form}
    Let $\mathcal E$ be a bounded quantum Dirichlet form on $L^2(M)$ with respect to $\Omega_\varphi$. There exists a self-dual $M$-$M$ correspondence $(\tilde \mathcal H,\tilde\mathcal J)$ and a vector $\xi\in\tilde\mathcal H$ such that
        \begin{itemize}
            \item $\tilde\mathcal J\xi=\xi$,
            \item $\mathcal E(a)=\int_{\mathbb R}\lVert\pi_l(\Delta_\varphi^{it}a)\xi-\xi\cdot J\pi_r(\Delta_\varphi^{it}a)^\ast J\rVert_{\mathcal H}^2\frac{2\,dt}{\cosh 2\pi t}$ for all $a\in M\Omega_\varphi\cap M^\prime\Omega_\varphi$.
        \end{itemize}
    Moreover, the map
    \begin{equation*}
        \tilde\delta\colon M\Omega_\varphi\cap M^\prime \Omega_\varphi\to \tilde\mathcal H,\,a\mapsto \pi_l(a)\xi-\xi\cdot J\pi_r(a)^\ast J
    \end{equation*}
    is closable and
    \begin{equation*}
        \lVert\tilde\delta(a)\rVert_{\tilde\mathcal H}^2=\operatorname{Re}\mathcal E(\Delta_\varphi^{1/4}a,\Delta_\varphi^{-1/4}a)\leq \mathcal E(\Delta_\varphi^{1/4}a)^{1/2}\mathcal E(\Delta_\varphi^{-1/4}a)^{1/2}.
    \end{equation*}

Let $L$ be the (bounded) positive self-adjoint operator such that $\mathcal E=Q_L$ and let $(\Phi_t)_{t\geq 0}$ be the associated uniformly continuous KMS-symmetric quantum Markov semigroup with generator $\mathcal L$. As a consequence of the Christensen--Evans theorem (see \cite[Proposition 4.1]{VW23} for the details), the operator $\mathcal L$ is the difference of two normal completely positive maps.

    Define
    \begin{equation*}
        \omega\colon M\odot M^\prime\to\mathbb C,\,x\otimes y^\prime=-\frac 1 2\langle\Omega_M,\mathcal L(x)y^\prime\Omega_M\rangle
    \end{equation*}
    Since $\mathcal L$ is the difference of two normal completely positive maps, $\omega$ extends to a bounded linear functional on the binormal tensor product $M\mathbin{\otimes_{\mathrm{bin}}} M^\prime$ (see \cite[Section 2]{EL77a}), still denoted by $\omega$.

    Let 
    \begin{equation*}
        I_0=\left\{\sum_{j=1}^n x_j\otimes y_j^\prime\right\vert\left.x_1,\dots,x_n\in M,y_1,\dots,y_n\in M^\prime,\sum_{j=1}^n x_j y_j^\prime \Omega=0\right\}
    \end{equation*}
    and $I=\overline I_0\subset M\mathbin{\otimes_{\mathrm{bin}}} M^\prime$, $B=I\cap I^\ast$.

    Note that $I_0\subset M\odot M^\prime$ is a left ideal and hence $I\subset M\mathbin{\otimes_{\mathrm{bin}}} M^\prime$ is a closed left ideal. Moreover, $\omega|_{B}$ is positive since
    \begin{align*}
        \omega\left(\sum_{j,k=1}^n x_j^\ast x_k\otimes (y_j^\prime)^\ast y_k^\prime\right)&=\lim_{t\to 0}\frac 1 t\sum_{j,k=1}^n \langle y_j^\prime\Omega,\Phi_t(x_j^\ast x_k)y_k^\prime\Omega\rangle\geq 0
    \end{align*}
    for $\sum_{j=1}^n x_j\otimes y_j^\prime\in I_0$.

    Let
    \begin{equation*}
        \alpha\colon M\odot M^\prime\to M\odot M^\prime,\,x\otimes y^\prime\mapsto J y^\prime J\otimes J x J.
    \end{equation*}
    The map $\alpha$ is a anti-linear, unital, multiplicative and self-adjoint ($\alpha(v)^\ast=\alpha(v^\ast)$) and satisfies $\alpha^2=\mathrm{id}$. Note that if $\psi\colon M\odot M^\prime\to\mathbb C$ is a binormal state, then $v\mapsto \overline{\psi(\alpha(v))}$ is again a binormal state. From this fact it follows easily that $\alpha$ extends to an isometric involution on $M\mathbin{\otimes_{\mathrm{bin}}} M^\prime$.

    Moreover, as a consequence of KMS symmetry,
    \begin{align*}
        \omega(\alpha(x\otimes y^\prime))
        &=\omega(J y^\prime J\otimes J xJ)\\
        &=-\frac 1 2\langle \Omega_\varphi,\mathcal L(J y^\prime J)J xJ\Omega_\varphi\rangle\\
        &=-\frac 1 2\langle J\Omega_\varphi,J y^\prime \mathcal L(x)\Omega_\varphi\rangle\\
        &=-\frac 1 2 \langle y^\prime \mathcal L(x)\Omega_\varphi,\Omega\varphi\rangle\\
        &=\overline{\omega(x\otimes y^\prime)}.
    \end{align*}

    The functional $\omega|_B$ can be (uniquely) extended to a positive linear functional on $B+\mathbb C 1$ and then by Hahn--Banach to a positive linear functional $\tilde\omega$ on $M\mathbin{\otimes_{\mathrm{bin}}} M^\prime$. A direct computation shows $\tilde\omega(\alpha(v))=\overline{\omega(v)}$ for $v\in B+\mathbb C 1$. Thus, otherwise replacing $\tilde \omega$ by the functional $\frac  12(\tilde\omega+\overline{\tilde\omega(\alpha(\cdot))})$, we may assume that $\tilde \omega\circ\alpha=\overline{\tilde \omega(\cdot)}$.

    Let $(\rho,\tilde\mathcal H,\xi)$ be the cyclic representation induced by $\tilde\omega$. The Hilbert space $\tilde\mathcal H$ becomes an $M$-$M$ correspondence with the left and right action defined by $x\eta y=\rho(x\otimes Jy^\ast J)\eta$.

    For $v,w\in M\mathbin{\otimes_{\mathrm{bin}}} M^\prime$ we have
    \begin{equation*}
        \langle \alpha(v)\xi,\alpha(w)\xi\rangle=\tilde\omega(\alpha(v^\ast w))=\overline{\tilde\omega(v^\ast w)}=\overline{\langle v\xi,w\xi\rangle}.
    \end{equation*}
    Thus there exists a unique anti-unitary involution $\tilde\mathcal J$ on $\tilde\mathcal H$ such that $\tilde\mathcal J(v\xi)=\alpha(v)\xi$ for all $v\in M\mathbin{\otimes_{\mathrm{bin}}} M^\prime$. A direct computation shows $\tilde\mathcal J(x\eta y)=y^\ast(\tilde\mathcal J \eta)x^\ast$ for $x,y\in M$ and $\eta\in (M\mathbin{\otimes_{\mathrm{bin}}} M^\prime)\xi$, and this identity extends to arbitrary $\eta\in \tilde\mathcal H$ by continuity. Furthermore, $\tilde\mathcal J\xi=\alpha(1)\xi=\xi$.

    If $a\in M\Omega_\varphi\cap M^\prime \Omega_\varphi$, then $\pi_l(a)\otimes 1-1\otimes \pi_r(a)\in I$, hence
    \begin{align*}
        \lVert\pi_l(a)\xi-\xi\cdot J\pi_r(a)^\ast J\rVert_{\tilde\mathcal H}^2&=\omega(\lvert\pi_l(a)\otimes 1-1\otimes \pi_r(a)\rvert^2)\\
        &=\frac  1 2\langle \Omega_\varphi,\mathcal L(\pi_l(a))^\ast \pi_r(a)\Omega_\varphi\rangle+\frac1  2\langle \Omega_\varphi,\mathcal L(\pi_l(a))\pi_r(a)^\ast\Omega_\varphi\rangle\\
        &=\frac 1 2\langle \Delta_\varphi^{1/4}\mathcal L(\pi_l(a))\Omega_\varphi,\Delta_\varphi^{-1/4}a\rangle+\frac 1 2\langle \Delta_\varphi^{-1/4}a,\Delta_\varphi^{1/4}\mathcal L(\pi_l(a))\Omega_\varphi\rangle\\
        &=\frac 1 2\mathcal E(\Delta_\varphi^{1/4}a,\Delta_\varphi^{-1/4}a)+\frac 1 2\mathcal E(\Delta_\varphi^{-1/4}a,\Delta_\varphi^{1/4}a).
    \end{align*}
    Note that the manipulation with the modular operator are justified as $M\Omega_\varphi\subset \operatorname{dom}(\Delta_\varphi^{1/4})$ and $M^\prime\Omega_\varphi\subset\operatorname{dom}(\Delta_\varphi^{-1/4})$. In particular, 
    \begin{equation*}
        M\Omega_\varphi\cap M^\prime\Omega_\varphi\subset \operatorname{dom}(\Delta_\varphi^{1/4}L\Delta_\varphi^{-1/4})\cap \operatorname{dom}(\Delta_\varphi^{-1/4}L\Delta_\varphi^{1/4}),
    \end{equation*}
    which implies that the quadratic form $Q$ with $\operatorname{dom}(Q)=M\Omega_\varphi\cap M^\prime\Omega_\varphi$ defined by
    \begin{equation*}
        Q(a)= \frac 1 2\mathcal E(\Delta_\varphi^{1/4}a,\Delta_\varphi^{-1/4}a)+\frac 1 2\mathcal E(\Delta_\varphi^{-1/4}a,\Delta_\varphi^{1/4}a)=\langle a,\frac 1 2(\Delta_\varphi^{1/4}L\Delta_\varphi^{-1/4}+\Delta_\varphi^{-1/4}L \Delta_\varphi^{1/4})a\rangle
    \end{equation*}
    is closable \cite[Lemma 10.16]{Sch12}. Thus $\tilde\delta$ as defined in the statement of the theorem is closable. Moreover, the bound $\lVert\tilde\delta(a)\rVert_{\tilde\mathcal H}^2\leq \mathcal E(\Delta_\varphi^{1/4}a)^{1/2}\mathcal E(\Delta_\varphi^{-1/4}a)^{1/2}$ follows from the equation above by Cauchy--Schwarz.

    Let $S=\{z\in\mathbb C\mid -1/4<\operatorname{Re} z<1/4\}$ and
    \begin{align*}
        f\colon\overline S\to\mathbb C,\,z\mapsto \mathcal E(\Delta_\varphi^{-\bar z}a,\Delta_\varphi^{z} a).
    \end{align*}
    Since $a\in\operatorname{dom}(\Delta_\varphi^{1/2})\cap\operatorname{dom}(\Delta_\varphi^{-1/2})$ and $\mathcal E$ is bounded, the function $f$ is continuous and bounded on $\overline S$ and analytic on $S$ by \cite[Lemma VI.2.3]{Tak03}. It satisfies $f(0)=\langle a,La\rangle=\mathcal E(a)$ and
    \begin{align*}
        f(-1/4+it)+f(1/4+it)&=\mathcal E(\Delta_\varphi^{1/4+it}a,\Delta_\varphi^{-1/4+it}a)+\mathcal E(\Delta_\varphi^{-1/4+it}a,\Delta_\varphi^{1/4+it}a)\\
        &=2\lVert\pi_l(\Delta_\varphi^{it}a)\xi-\xi\cdot J\pi_r(\Delta_\varphi^{it}a)^\ast J\rVert^2
    \end{align*}
    by the previous computation.

    Hence we can apply \Cref{lem:appl_residue_thm} to get
    \begin{align*}
        \mathcal E(a)&=f(0)\\
        &=\int_{\mathbb R}(f(-1/4+it)+f(1/4+it))\frac{dt}{\cosh 2\pi t}\\
        &=\int_{\mathbb R}\lVert\pi_l(\Delta_\varphi^{it}a)\xi-\xi\cdot J\pi_r(\Delta_\varphi^{it}a)^\ast J\rVert^2\frac{2\,dt}{\cosh 2\pi t}.\qedhere
    \end{align*}

For specific bounded quantum Dirichlet forms, for which the generator of the associated quantum Markov semigroup takes the form $\mathcal L=1-\Psi$ with a KMS-symmetric ucp map $\Psi$, a form of this representation theorem was proven in \cite{Wir25} and used to establish the triangle inequality for a quantum Wasserstein distance. In this special case, the vector $\xi\in \tilde\mathcal H$ is always a bounded vector so that the quantum Dirichlet form takes the form
    \begin{equation*}
        \mathcal E(a)=\int_{\mathbb R}\lVert(L_\varphi(\xi)-R_\varphi(\xi))\Delta_\varphi^{it}a\rVert_{\tilde\mathcal H}^2\frac{2\,dt}{\cosh 2\pi t},\quad a\in L^2(M).
    \end{equation*}

\label{prop:trans_weighted_L2}
    Let $H$ be a Hilbert space. The family $(\mathcal V_s)_{s\in \mathbb R}$ given by 
    \begin{equation*}
        \mathcal V_s\colon L^2(\mathbb R,\mu;H)\to L^2(\mathbb R,\mu;H),\,(\mathcal V_s \xi)(t)=\xi(s+t)
    \end{equation*}
    for $s\in\mathbb R$ is a strongly continuous group, $\lVert\mathcal V_s\rVert\leq e^{\pi\lverts\rvert}$ for all $s\in\mathbb R$ and $\mathcal V_{-i/2}$ is accretive.

Since $\frac{\cosh 2\pi t}{\cosh 2\pi(t-s)}\in [e^{-2\pi\lverts\rvert},e^{2\pi\lverts\rvert}]$ for all $s,t\in\mathbb R$, we have
    \begin{align*}
        \lVert\mathcal V_s\xi\rVert^2=\int_\mathbb R \lVert\xi(t)\rVert^2\frac{\cosh 2\pi t}{\cosh{2\pi(t-s)}}\frac{2\,dt}{\cosh 2\pi t}\leq e^{2\pi\lverts\rvert}\lVert\xi\rVert^2
    \end{align*}
    for all $\xi\in L^2(\mathbb R,\mu;H)$. For strong continuity, it is therefore enough to prove $\lVert\mathcal V_s \xi-\xi\rVert_2\to 0$ for $\xi\in C_c(\mathbb R;H)$, which is obvious.

    It remains to show that $\mathcal V_{-i/2}$ is accretive. Let $S=\{z\in \mathbb C\mid -\frac 1 2\leq \operatorname{Im} z\leq 0\}$. By definition, $\operatorname{dom}(\mathcal V_{-i/2})\subset \operatorname{dom}(\mathcal V_z)$ for all $z\in S$, and if $\xi\in\operatorname{dom}(\mathcal V_{-i/2})$, then $S\to L^2(\mathbb R,\mu;\mathcal H)$, $z\mapsto \mathcal V_z \xi$ is continuous and analytic on the interior of $S$.

    Let $\varphi\in C_c^\infty(\mathbb R)$ be positive with $\int_\mathbb R\varphi(t)\,dt=1$ and let $\varphi_\varepsilon(t)=\varepsilon^{-1}\varphi(t/\varepsilon)$ for $\varepsilon>0$. Define
    \begin{equation*}
        h_\varepsilon\colon \{z\in \mathbb C\mid -1/4\leq \operatorname{Re} z\leq 1/4\}\to \mathbb C,\,z\mapsto\int_{\mathbb R}\varphi_\varepsilon(t)\langle \mathcal V_{i\bar z-i/4}\xi(t),\mathcal V_{-iz-i/4}\xi(t)\rangle_\mathcal H\,dt.
    \end{equation*}
    Note that $L^1(\mathbb R,\mu)\subset L^1_{\mathrm{loc}}(\mathbb R)$ so that the integral is well-defined. For $s\in\mathbb R$ let $V(s)=-\log\frac{2}{\cosh 2\pi s}$. By \Cref{lem:appl_residue_thm}, we have 
    \begin{align*}
        \int_{\mathbb R}\frac{h_\varepsilon(-1/4+is)+h_\varepsilon(1/4+is)}{2}e^{-V(s)}\,ds=h_\varepsilon(0)=\int_\mathbb R\varphi_\varepsilon(t)\lVert\mathcal V_{-i/4}\xi(t)\rVert_\mathcal H^2\,dt\geq 0.
    \end{align*}
    On the other hand,
    \begin{align*}
        \int_\mathbb R h_\varepsilon(-1/4+is)e^{-V(s)}\,ds
        &=\int_\mathbb R\int_\mathbb R\varphi_\varepsilon(t)\langle \mathcal V_{s-i/2}\xi(t),\mathcal V_{s}\xi(t)\rangle_\mathcal H e^{-V(s)}\,dt\,ds\\
        &=\int_\mathbb R\int_\mathbb R\varphi_\varepsilon(t)\langle \mathcal V_{-i/2}\xi(s+t),\xi(s+t)\rangle_\mathcal H e^{-V(s)}\,dt\,ds\\
        &=\int_\mathbb R\int_\mathbb R \langle \mathcal V_{-i/2}\xi(s),\xi(s)\rangle_\mathcal H e^{-V(s)}\int_{\mathbb R}\varphi_\varepsilon(t) e^{V(s)-V(s-t)}\,dt\,ds.\\
    \end{align*}
    If $\varepsilon_n\to 0$, then $\int_{\mathbb R}\varphi_{\varepsilon_n}(t) e^{V(s)-V(s-t)}\,dt\to 1$ for every $s\in\mathbb R$ by the properties of the mollifier. Moreover, if $\operatorname{supp}\varphi\subset [-R,R]$, then $\int_{\mathbb R}\varphi_\varepsilon(t) e^{V(s)-V(s-t)}\,dt\leq \int_{\mathbb R}\varphi_\varepsilon(t)e^{2\pi \lvertt\rvert}\,dt\leq e^{2\pi R\varepsilon}$. Therefore,
    \begin{align*}
        \int_\mathbb R h_{\varepsilon_n}(-1/4+is)e^{-V(s)}\,ds\to \int_\mathbb R \langle \mathcal V_{-i/2}\xi(s),\xi(s)\rangle_\mathcal H e^{-V(s)}\,ds=\langle \mathcal V_{-i/2}\xi,\xi\rangle_\mathcal H
    \end{align*}
    by the dominated convergence theorem.

    An analogous argument shows
    \begin{equation*}
        \int_\mathbb R h_{\varepsilon_n}(1/4+is)e^{-V(s)}\,ds\to\langle\xi,\mathcal V_{-i/2}\xi\rangle_\mathcal H.
    \end{equation*}
    Altogether we have shown $\operatorname{Re}\langle \xi,\mathcal V_{-i/2}\xi\rangle\geq 0$.

First assume that $L$ generates a bounded conservative completely Dirichlet form. By \Cref{thm:int_rep_form} there exists an $M$-$M$ correspondence $\tilde\mathcal H$, an anti-unitary involution $\tilde\mathcal J\colon \tilde\mathcal H\to \tilde\mathcal H$ and a vector $\xi\in \tilde\mathcal H$ such that $\tilde \mathcal J(x\xi y)=y^\ast \xi x^\ast$ for all $x,y\in M$ and
    \begin{equation*}
        \mathcal E(a)=\int_{\mathbb R}\lVert\pi_l(\Delta_\varphi^{it}a)\xi-\xi\cdot J\pi_r(\Delta_\varphi^{it}a)^\ast J\rVert_{\tilde\mathcal H}^2\frac{2\,dt}{\cosh 2\pi t},\quad a\in M\Omega\cap M^\prime\Omega.
    \end{equation*}
    We may assume without loss of generality that $\tilde \mathcal H$ is the closed bimodule generated by $\xi$.

    On $L^2(\mathbb R,\mu;\tilde\mathcal H)$ define a bimodule structure by $(x\eta y)(t)=\sigma^\varphi_t(x)\eta(t)\sigma^\varphi_t(y)$ for $x,y\in M$ and $\eta\in L^2(\mathbb R,\mu;\tilde\mathcal H)$. Let 
    \begin{equation*}
        \delta\colon M\Omega\cap M^\prime\Omega\to L^2(\mathbb R,\mu;\tilde\mathcal H),\,\delta(a)(t)=\pi_l(\Delta_\varphi^{it}a)\xi-\xi\cdot J\pi_r(\Delta_\varphi^{it}a)^\ast J
    \end{equation*}
    and let $\mathcal H$ be the closed bimodule generated by the range of $\delta$. Since
    \begin{align*}
        \lVert\delta(a)\rVert_\mathcal H^2=\int_{\mathbb R}\lVert\pi_l(\Delta_\varphi^{it}a)\xi-\xi\cdot J\pi_r(\Delta_\varphi^{it}a)^\ast J\rVert_{\tilde\mathcal H}^2\frac{2\,dt}{\cosh 2\pi t}=\mathcal E(a)=\langle a,L(a)\rangle_2
    \end{align*}
    for $a\in M\Omega\cap M^\prime\Omega$, the operator $\delta$ extends to a bounded linear operator from $L^2(M)$ to $\mathcal H$, still denoted by $\delta$, such that $\delta^\ast \delta=L$.

    Define $(\mathcal J\eta)(t)=\tilde\mathcal J\eta(t)$ and $(\mathcal V_s\eta)(t)=\eta(s+t)$ for $\eta\in \mathcal H$. The claimed properties of the quadruple $(\mathcal H,\mathcal J,(\mathcal V_s)_{s\in\mathbb R},\delta)$ are now easy to check except for accretivity of $\mathcal V_{-i/2}$, which was proven in \Cref{prop:trans_weighted_L2}.

    For uniqueness, we have already shown in \cite[Theorem 4.7]{VW23} that the triple $(\mathcal H,\mathcal J,\delta)$ is essentially uniquely determined by $L$. Moreover, the properties (ii) and (iv) determine $(\mathcal V_s)_{s\in\mathbb R}$ uniquely on the dense subset $
    \operatorname{span}\{x\delta(a)y\mid a\in L^2(M),x,y\in M\}$ of $\mathcal H$.

    From uniqueness it follows that if $L$ commutes strongly with $\Delta_\varphi$, then $(\mathcal V_s)_{s\in \mathbb R}$ is a strongly continuous unitary group and $\mathcal V_{-i/2}$ is positive self-adjoint by Stone's theorem. Conversely, if $\mathcal V_{-i/2}$ is positive self-adjoint (and injective since $\mathcal V_{i/2}\mathcal V_{-i/2}=1$ on $\operatorname{dom}(\mathcal V_{-i/2})$), then $\mathcal V_s=\mathcal V_{-i/2}^{2is}$ is unitary and thus
    \begin{equation*}
        \Delta_\varphi^{-is}L\Delta_\varphi^{is}=\Delta_\varphi^{-is}\delta^\ast\delta \Delta_\varphi^{is}=\delta^\ast \mathcal V_s^\ast\mathcal V_{s}\delta=\delta^\ast \delta=L.
    \end{equation*}
    Now assume that $(\mathcal H,\mathcal J,(\mathcal V_s)_{s\in\mathbb R},\delta)$ is a quadruple with the properties from the theorem and let $L=\delta^\ast \delta$. Clearly, $L$ is a positive self-adjoint operator. Moreover, the properties of $\mathcal J$ and $\delta$ imply $LJ=JL$ and $L\Omega_\varphi=0$. Note that if $x,y\in \operatorname{dom}(\sigma^\varphi_{z})$ and $a\in \operatorname{dom}(\Delta_\varphi^{iz})$, then $x\delta(a)y\in \operatorname{dom}(\mathcal V_{z})$ and $\mathcal V_z(x\delta(a)y)=\sigma^\varphi_z(x)\delta(\Delta_\varphi^{iz}a)\sigma^\varphi_z(y)$. Indeed, for $z\in \mathbb R$ this is immediate from the properties of $(\mathcal V_s)_{s\in \mathbb R}$ and $\delta$ and for general $z\in\mathbb C$ it follows them from the identity theorem for analytic functions.

    Let $\mathcal E$ be the closed quadratic form associated with $L$. It remains to show that $\mathcal E(a_+,a_-)\leq 0$ for all $a\in \ker(1-J)$. In fact, since taking positive and negative parts is continuous, it suffices to show this inequality for $a$ in the subset $\{x^\ast\Omega_\varphi x-y\Omega_\varphi y^\ast\mid x,y\in M,\,xy=0\}$ of $\ker (1-J)$, which is dense by \Cref{lem:dense_real_part}.

    Let $a=x^\ast \Omega_\varphi x-y\Omega_\varphi y^\ast$ with $x,y\in M$ such that $xy=0$. By Haagerup's approximation technique \cite[Lemma 1.3]{Haa75}, there exist bounded sequences $(x_n)$, $(y_n)$ of entire analytic elements for $\sigma^\varphi$ such that $x_n\to x$ and $y_n\to y$ in strong$^\ast$ topology. In particular, $x_ny_n\to 0$ in strong$^\ast$ topology.

    We have
    \begin{align*}
        \mathcal E(a_+,a_-)&=\langle \delta(x^\ast \Omega_\varphi x),\delta(y\Omega_\varphi y^\ast)\rangle_\mathcal H\\
        &=\langle x^\ast \delta(\Omega_\varphi x)+\delta(x^\ast \Omega_\varphi)x,\delta(y\Omega_\varphi)y^\ast+y\delta(\Omega_\varphi y^\ast)\rangle\\
        &=\langle \delta(\Omega_\varphi x)y,x\delta(y\Omega_\varphi)\rangle+\langle y^\ast \delta(x^\ast\Omega_\varphi),\delta(\Omega_\varphi y^\ast)x^\ast\rangle\\
        &=\langle \delta(\Omega_\varphi x)y,x\delta(y\Omega_\varphi)\rangle+\langle \mathcal J(\delta(\Omega_\varphi x)y),\mathcal J(x\delta(y\Omega_\varphi))\rangle\\
        &=2\operatorname{Re}\langle \delta(\Omega_\varphi x)y,x\delta(y\Omega_\varphi)\rangle
        \end{align*}
        Now we use that $\delta(\Omega_\varphi x_n)y_n\to \delta(\Omega_\varphi x)y$ and $x_n\delta(y_n\Omega_\varphi)\to x\delta(y\Omega_\varphi)$ to obtain
        \begin{align*}
        \mathcal E(a_+,a_-)
        &=2\lim_{n\to\infty}\operatorname{Re}\langle \delta(\Omega_\varphi x_n)y_n,x_n\delta(y_n\Omega_\varphi)\rangle\\
        &=2\lim_{n\to\infty}\operatorname{Re}\langle \delta(\Omega_\varphi x_n y_n)-\sigma^\varphi_{-i/2}(x_n)\delta(\Omega_\varphi y_n),x_n\delta(y_n\Omega_\varphi)\rangle\\
        &=-2\lim_{n\to\infty}\operatorname{Re}\langle \mathcal V_{-i/2}(x_n\delta(y_n\Omega_\varphi)),x_n \delta(y_n\Omega_\varphi)\rangle\\
        &\leq 0.\qedhere
    \end{align*}

Clearly $\mathcal L_n(1)=0$ and $\mathcal L_n(x^\ast)=\mathcal L_n(x)^\ast$ for $x\in B(p_n H)$. Moreover, if $x_1,\dots,x_m$, $y_1,\dots,y_m\in B(p_n H)$ such that $0=\sum_{j=1}^m x_j y_j=\sum_{j=1}^m x_j p_n y_j $, then 
    \begin{equation*}
        \sum_{j,k=1}^my_j^\ast p_n\mathcal L(p_n x_j^\ast x_k p_n)p_n y_k\leq 0
    \end{equation*}
    since $\mathcal L$ is conditionally completely negative. Therefore, $\mathcal L_n$ generates a quantum Markov semigroup on $B(p_n H)$.

    Additionally, for any $x,y\in B(p_n H)$ we have
\begin{align*}
    \mathrm{Tr}(\rho_n^{1/2}x^*\rho_n^{1/2}\mathcal{L}_n(y))&=\mathrm{Tr}(\rho_n^{1/2}x^*\rho_n^{1/2}p_n\mathcal{L}(y)p_n)\\
    &=\mathrm{Tr}(\rho^{1/2}p_nx^*p_n\rho^{1/2}\mathcal L(y))\\
    &=\mathrm{Tr}(\rho^{1/2}\mathcal L(p_nx^*p_n)\rho^{1/2}y)\\
    &=\mathrm{Tr}(\rho_n^{1/2}\mathcal{L}_n(x^*)\rho_n^{1/2}y),
\end{align*}
where we use that $p_n$ and $\rho$ commute, $\mathcal L$ is KMS-symmetric and $p_nzp_n=z$ for any $z\in B(p_n H)$. Consequently, $\mathcal L_n$ is a KMS-symmetric generator on $B(p_n H)$.

Let $M$ be a von Neumann algebra. A linear map $\mathcal L\colon M\to M$ is the generator of a uniformly continuous quantum Markov semigroup if and only if there exist an element $k$ of $M$ and a normal completely positive map $\Psi$ on $M$ such that
    \begin{equation*}
        \mathcal L(x)=k^*x+xk-\Psi(x)
    \end{equation*}
    for all $x\in M$.

\label{thm:CE_KMS}
    If $\mathcal L$ is a KMS-symmetric generator of a uniformly continuous quantum Markov semigroup, then there exist an element $k\in M$ with $\lVertk\rVert\leq 4\lVert\mathcal L\rVert$ and a normal KMS-symmetric completely positive map $\Psi$ on $M$ such that
    $\lVert\Psi\rVert\leq 2\lVert\mathcal L\rVert$, $k^*+k=\Psi(1)$ and 
    \begin{equation*}
        \mathcal L(x)=k^*x+xk-\Psi(x).
    \end{equation*}

Let $\tilde{\Psi}$ and $\tilde{k}$ be as in the Christensen-Evans theorem such that
    \begin{equation*}
        \mathcal L(x)=\tilde{k}^*x+x\tilde k-\tilde{\Psi}(x)
    \end{equation*}
    for all $x\in M$. Let $\tilde{\Psi}(\cdot)=\sum_{j\in I}V_j^*\cdot V_j$ be the Kraus decomposition of $\tilde{\Psi}$ and let $\eta\in H$ be an eigenvector of $\rho$ with eigenvalue $\lambda$. Let $n\in \mathbb{N}$ be arbitrary such that $\lambda\in [1/n,n]$. In this case, $\mathcal L_n$ is given by
    \begin{equation*}
        \mathcal L_n(x)=p_nk^*p_nx+xp_nkp_n-\sum_{j\in I}p_nV_j^*p_n x p_n V_j p_n
    \end{equation*}
    for all $x\in M_n$. Since $\mathcal L_n$ is KMS-symmetric, we have
    \begin{align*}
        \mathrm{Tr}\left(\rho_n^{1/2}\mathcal L_n(x^*)\rho_n^{1/2}y\right)=&\mathrm{Tr}\left(\rho_n^{1/2}x^*\rho_n^{1/2}\mathcal L_n(y)\right)\\
        =&\mathrm{Tr}\left(\rho_n^{1/2}x^*\rho_n^{1/2}(p_nk^*p_n y+yp_nkp_n-\sum_{j\in I}p_nV_j^*p_nyp_nV_jp_n)\right)\\
        =&\mathrm{Tr}\Bigg(\rho_n^{1/2}(\sigma^\varphi_{i/2}(p_nkp_n)x^*+x^*\sigma^\varphi_{-i/2}(p_nk^*p_n)\\
        &-\sum_{j\in I}\sigma^\varphi_{i/2}(p_nV_jp_n)x^*\sigma^\varphi_{-i/2}(p_nV_j^*p_n))\rho_n^{1/2}y\Bigg),
    \end{align*}
    using the fact that $\sigma^\varphi_{-i/2}$ and $\sigma^\varphi_{i/2}$ are bounded on $B(p_n H)$. Now we can define
    \begin{equation*}
        \Psi'(x)=\frac{1}{2}\sum_{j\in I}\bigg(p_nV_j^*p_nxp_nV_jp_n+\sigma^\varphi_{i/2}(p_nV_jp_n)x\sigma^\varphi_{-i/2}(p_nV_j^*p_n)\bigg)
    \end{equation*}
    for $x\in B(p_n H)$ and 
    \begin{equation*}
        k'=\frac{1}{2}(p_nkp_n+\sigma^\varphi_{-i/2}(p_nk^*p_n)).
    \end{equation*}
    These definitions give
    \begin{equation*}
        \mathcal L_n(x)=(k')^*x+xk'-\Psi'(x),\quad x\in B(p_n H),
    \end{equation*}
    and by construction $\Psi'$ is KMS-symmetric. We also see that $k'=\sigma_{-i/2}((k')^*)$. Together with the relation that $k'+(k')^*=\Psi'(1)$, this gives
    \begin{equation*}
        (k')^*=(\mathrm{id}+\sigma^\varphi_{-i/2})^{-1}(\Psi'(1))\text{ and }k'=(\mathrm{id}+\sigma_{i/2})^{-1}(\Psi'(1)).
    \end{equation*}
    We have now obtained a KMS-symmetric $\Psi'$, but we are yet to establish a bound on its norm. For this, we need to modify $\Psi'$ further. Let $\omega_j=\langle \eta,V_j\eta\rangle$. Note that
    \begin{equation*}
        \omega_j=\langle \eta,p_nV_jp_n\eta\rangle=\langle \eta,\sigma^\varphi_{i/2}(p_nV_jp_n)\eta\rangle
    \end{equation*}
    by choice of $\eta$. Now define $W_j=V_j-\omega_j$, $\Psi_n:B(p_n H)\rightarrow B(p_nH)$ by 
    \begin{equation*}
        \Psi_n(x)=\frac{1}{2}\sum_{j\in I}\bigg(p_nW_j^*p_nxp_nW_jp_n+\sigma^\varphi_{i/2}(p_nW_jp_n)x\sigma^\varphi_{-i/2}(p_nW_j^*p_n)\bigg)
    \end{equation*}
    and $k_n=(\mathrm{id}+\sigma_{i/2})^{-1}(\Psi_n(1))$. We want to show that the change from $V_j$ to $W_j$ does not affect the generator. Let $V\in B(p_n H)$ and $\omega\in \mathbb{C}$ be arbitrary and let $W=V-\omega$. Then we compute that
    \begin{align}
        &(\mathrm{id}+\sigma_{-i/2})^{-1}(W^*W)x+x(\mathrm{id}+\sigma_{i/2})^{-1}(W^*W)-W^*xW\nonumber\\
        =&(\mathrm{id}+\sigma_{-i/2})^{-1}(V^*V)x+x(\mathrm{id}+\sigma_{i/2})^{-1}(V^*V)-V^*xV\nonumber\\
        &-(\mathrm{id}+\sigma_{-i/2})^{-1}(\overline{\omega}V+\omega V^*)x+x(\mathrm{id}+\sigma_{i/2})^{-1}(\overline{\omega}V+\omega V^*)+\overline{\omega}xV+\omega V^*x.\label{eq:V-W-equality-1}
    \end{align}
    Likewise, denoting $\sigma_{i/2}(W)$ and $\sigma_{i/2}(V)$ by $\tilde{W}$ and $\tilde{V}$, respectively,
        \begin{align}
        &(\mathrm{id}+\sigma_{-i/2})^{-1}(\tilde{W}\tilde{W}^*)x+x(\mathrm{id}+\sigma_{i/2})^{-1}(\tilde{W}\tilde{W}^*)-\tilde{W}x\tilde{W}^*\nonumber\\
        =&(\mathrm{id}+\sigma_{-i/2})^{-1}(\tilde{V}\tilde{V}^*)x+x(\mathrm{id}+\sigma_{i/2})^{-1}(\tilde{V}\tilde{V}^*)-\tilde{V}x\tilde{V}^*\nonumber\\
        &-(\mathrm{id}+\sigma_{-i/2})^{-1}(\overline{\omega}\tilde{V}+\omega \tilde{V}^*)x+x(\mathrm{id}+\sigma_{i/2})^{-1}(\overline{\omega}\tilde{V}+\omega \tilde{V}^*)+\overline{\omega}\tilde{V}x+\omega x\tilde{V}^*.\label{eq:V-W-equality-2}
    \end{align}
    Now 
    \begin{equation*}
        V+\tilde{V}=V+\sigma_{i/2}(V)=(\mathrm{id}+\sigma_{i/2})(V)=(\mathrm{id}+\sigma_{-i/2})(V^*),
    \end{equation*}
    so 
    \begin{equation*}
        (\mathrm{id}+\sigma_{-i/2})^{-1}(\overline{\omega}V)+(\mathrm{id}+\sigma_{-i/2})^{-1}(\overline{\omega}\tilde{V})=\overline{\omega}V
    \end{equation*}
    Together with an analogous derivation for the other terms, this shows that the terms proportional to $\omega$ and $\overline{\omega}$ in Equations \ref{eq:V-W-equality-1} and \ref{eq:V-W-equality-2} add up to zero.

















    This proves that changing $V_j$ to $V_j-\omega_j$ does not change the corresponding generator, so
    \begin{equation*}
        \mathcal L_n(x)=k_n^*x+xk_n-\Psi_n(x),\quad x\in B(p_n H).
    \end{equation*}

    Let $\varepsilon>0$ be arbitrary and let $\xi\in p_nH$ be a vector such that $\langle \xi,\Psi_n(1)\xi\rangle\geq \lVert\Psi_n(1)\rVert-\varepsilon$. We now consider the element $\xi\eta^*\in B(p_n H)$ defined as the map $\zeta\mapsto \xi\langle \eta,\zeta\rangle$. We will now lower bound the norm of $\mathcal L_n(\xi\eta^*)$ by computing $\operatorname{Re}\langle \xi,\mathcal L_n(\xi\eta^*)\eta\rangle$. First, observe that
    \begin{align*}
        \langle \xi,\Psi_n(\xi\eta^*)\eta\rangle&=\frac{1}{2}\sum_{j\in I}\langle \xi,p_nW_j^*p_n\xi\eta^*p_nW_jp_n\eta\rangle+\langle \xi,\sigma^\varphi_{i/2}(p_nW_jp_n)\xi\eta^*\sigma^\varphi_{-i/2}(p_nW_j^*p_n)\eta\rangle\\
        &=\frac{1}{2}\sum_{j\in I}\langle \xi,p_nW_j^*p_n\xi\rangle\langle \eta,p_nW_jp_n\eta\rangle+\langle \xi,\sigma^\varphi_{i/2}(p_nW_jp_n)\xi\rangle\langle \eta,\sigma^\varphi_{-i/2}(p_nW_j^*p_n)\eta\rangle\\
        &=0.
    \end{align*}
    Then
    \begin{align*}
        \operatorname{Re}\langle \xi,\mathcal L_n(\xi\eta^*)\eta\rangle&=\operatorname{Re}\left(\langle \xi,(\mathrm{id}+\sigma^\varphi_{-i/2})^{-1}(\Phi_n(1))\xi\eta^*\eta\rangle+\langle \xi,\xi\eta^*(\mathrm{id}+\sigma^\varphi_{i/2})^{-1}(\Psi_n(1))\eta\rangle\right)\\
        &=\operatorname{Re}\left(\langle \xi,(\mathrm{id}+\sigma^\varphi_{-i/2})^{-1}(\Psi_n(1))\xi\rangle+\langle \eta,(\mathrm{id}+\sigma_{i/2})^{-1}(\Psi_n(1))\eta\rangle\right)\\
        &=\frac{1}{2}\left(\langle \xi,\Psi_n(1)\xi\rangle+\langle \eta,\Psi_n(1)\eta\rangle\right).
    \end{align*}
    Since $\Psi_n(1)$ is positive, this shows that $\operatorname{Re}\langle \xi,\mathcal L_n(\xi\eta^*)\eta\rangle\geq (\lVert\Psi_n(1)\rVert-\varepsilon)/2$. Since $\Psi_n$ is completely positive and $\varepsilon$ was arbitrary, we conclude that $\lVert\Psi_n\rVert\leq 2\lVert\mathcal L_n\rVert$.

    Next we obtain a norm bound for $k_n$. Let $\varepsilon>0$ and let $\xi,\xi'\in H$ be unit vectors such that $\langle \xi',k_n^*\xi\rangle\geq \lVertk_n^*\rVert-\varepsilon$. By construction, we have
    \begin{equation*}
        \langle \eta,k_n\eta\rangle=\langle \eta,\sigma_{-i/2}(k_n^*)\eta\rangle=\langle \eta,k_n^*\eta\rangle,
    \end{equation*}
    so 
    \begin{equation*}
        |\langle \eta,k_n\eta\rangle|=|\frac{1}{2}\langle \eta,\Psi_n(1)\eta\rangle|\leq \frac{1}{2}\lVert\Psi_n\rVert.
    \end{equation*}
    On the one hand, 
    \begin{equation*}
        |\langle \xi',(\mathcal L_n+\Psi_n)(\xi\eta^*)\eta\rangle|\leq \lVert\mathcal L_n+\Psi_n\rVert\leq 3\lVert\mathcal L\rVert
    \end{equation*}
    and, on the other hand,
    \begin{equation*}
        \langle \xi',(\mathcal L_n+\Psi_n)(\xi\eta^*)\eta\rangle=\langle \xi',k_n^*\xi\rangle\langle \eta,\eta\rangle+\langle \xi',\xi\rangle\langle \eta,k_n\eta\rangle.
    \end{equation*}
    From this we conclude that
    \begin{align*}
        |\langle \xi',k_n^*\xi\rangle|&\leq |\langle \xi',(\mathcal L_n+\Psi_n)(\xi\eta^*)\eta\rangle|+|\langle \xi',\xi\rangle\langle \eta,k_n\eta\rangle|\\
        &\leq 3\lVert\mathcal L\rVert+\frac{1}{2}|\langle \xi',\xi\rangle|\lVert\Psi_n\rVert\\
        &\leq 4\lVert\mathcal L\rVert.
    \end{align*}

    By the Banach--Alaoglu theorem, there exist subnets $(k_{n_\alpha})$ and $(\Psi_{n_\alpha})$ and $k\in B(H)$, $\Psi\in B(B(H))$ such that $k_{n_\alpha}\to k$ in weak$^\ast$ topology and $\Psi_{n_\alpha}(p_{n_\alpha}\cdot p_{n_{\alpha}})\to \Psi$ in point-weak$^\ast$ topology. The limit $\Psi$ is a unital completely positive map that is KMS-symmetric with respect to $\varphi$, hence normal. The previous norm bounds imply $\lVertk\rVert\leq 4\lVert\mathcal L\rVert$ and $\lVert\Psi\rVert\leq 2\lVert\mathcal L\rVert$.

    Moreover, passing to the limit in $p_n\mathcal L(p_n xp_n)p_n=k_n^\ast p_n x p_n+p_n xp_n k_n-\Psi_n(p_nxp_n)$ for $x\in B(H)$, we obtain
    \begin{equation*}
        \mathcal L(x)=k^*x+xk-\Psi(x),\quad x\in B(H).\qedhere
    \end{equation*}

\label{thm:char_bdd_type_I}
    If $\mathcal E$ is a bounded completely Dirichlet form on $S^2(H)$ with respect to $\rho^{1/2}$, then there exists a family $(V_j)_{j\in I}$ in $\operatorname{dom}(\sigma^\varphi_{i/2})$ such that $\sigma_{i/2}(V_j)=V_j^\ast$ for all $j\in I$, $\sum_{j\in I}V_j^\ast V_j$ converges in strong operator topology and
    \begin{equation*}
        \mathcal E(A)=\sum_{j\in I}\int_\mathbb R\lVertV_j\rho^{it}A\rho^{-it}-\rho^{it}A \rho^{-it}V_j^\ast\rVert_2^2\frac{2\,dt}{\cosh 2\pi t},\quad A\in S^2(H).
    \end{equation*}
    Conversely, if $(V_j)_{j\in I}$ is a family in $\operatorname{dom}(\sigma^\varphi_{i/2})$ such that $\sigma_{i/2}(V_j)=V_j^\ast$ for all $j\in I$ and $\sum_{j\in I}V_j^\ast V_j$ converges in strong operator topology, then
    \begin{equation*}
        \mathcal E(A)=\sum_{j\in I}\int_\mathbb R\lVertV_j\rho^{it}A\rho^{-it}-\rho^{it}A \rho^{-it}V_j^\ast\rVert_2^2\frac{2\,dt}{\cosh 2\pi t},\quad A\in S^2(H),
    \end{equation*}
    defines a bounded quantum Dirichlet form on $S^2(H)$ with respect to $\rho^{1/2}$.

First let $\mathcal E$ be a bounded quantum Dirichlet form and let $\mathcal L$ be the generator of the uniformly continuous quantum Markov semigroup on $B(H)$ associated with $\mathcal E$. By \Cref{thm:CE_KMS}, there exist $k\in B(H)$ and a KMS-symmetric completely positive map $\Psi\colon B(H)\to B(H)$ such that $\mathcal L(x)=k^\ast x+xk-\Psi(x)$ for all $x\in B(H)$. Let $\Psi(x)=\sum_{j\in I}V_j^*xV_j$ be a Kraus decomposition of $\Psi$. In particular, this means that the sum $\sum_{j\in I}V_j^\ast V_j$ converges in strong operator topology. Note that $\lVertV_j\rVert^2=\lVertV_j^\ast V_j\rVert\leq \lVert\Psi(1)\rVert=\lVert\Psi\rVert$.

The first step is to show that $V_j\in\operatorname{dom}(\sigma^\varphi_{i/2})$ and $\lVert\sigma^\varphi_{i/2}(V_j)\rVert\leq \sqrt{\lVert\Psi\rVert}$ for each $j\in I$. As before, let $p_n=\chi_{[1/n,n]}(\rho)$ and consider the map $\Psi_n=p_n\Psi(\cdot)p_n$ on $B(p_nH)$. It has Kraus decomposition $\Psi_n(x)=\sum_{j\in I}(p_n V_j p_n)^\ast x(p_n V_j p_n)$.

By KMS symmetry,
\begin{align*}
    \mathrm{Tr}(\Psi_n(x)\rho^{1/2}y\rho^{1/2})&=\sum_j\mathrm{Tr}(x\rho^{1/2}p_nV_j^\ast y V_j p_n\rho^{1/2})\\
    &=\sum_j\mathrm{Tr}(\sigma^\varphi_{i/2}(p_n V_j p_n) x \sigma^\varphi_{i/2}(p_n V_j p_n)^\ast\rho^{1/2}y\rho^{1/2})
\end{align*}
for $x,y\in B(p_nH)$. In particular,
\begin{equation*}
    \lVert\sigma^\varphi_{i/2}(p_n V_j p_n)\rVert^2=\lVert\sigma^\varphi_{i/2}(p_n x p_n)\sigma^\varphi_{i/2}(p_n x p_n)^\ast\rVert\leq \lVert\Psi_n(1)\rVert\leq \lVert\Psi\rVert.
\end{equation*}
Since $p_n V_j p_n\to V_j$ in weak$^\ast$ topology and $\sigma^\varphi_{i/2}$ is weak$^\ast$ closed by \cite[Theorem 2.4]{CZ76}, it follows that $V_j\in \operatorname{dom}(\sigma^\varphi_{i/2})$ and $\lVert\sigma^\varphi_{i/2}(V_j)\rVert\leq \sqrt{\lVert\Psi\rVert}$. Since $\operatorname{dom}(\sigma^\varphi_{i/4})\subset \operatorname{dom}(\sigma^\varphi_{i/2})$ by definition, we conclude that $V_j\in \operatorname{dom}(\sigma^\varphi_{i/4})$ and the Phragmen--Lindelöf theorem implies $\lVert\sigma^\varphi_{i/4}(V_j)\rVert\leq \max\{\lVertV_j\rVert,\lVert\sigma^\varphi_{i/2}(V_j)\rVert\}\leq \sqrt{\lVert\Psi\rVert}$.



Now define $V_j^{+}=e^{i\pi/4}V_j+e^{-i\pi/4}\sigma^\varphi_{i/2}(V_j)^*$ and $V_j^-=e^{-i\pi/4}V_j+e^{i\pi/4}\sigma^\varphi_{i/2}(V_j)^*$. A direct computation shows
\begin{align*}
    V_j^{+*}xV_j^{+}+V_j^{-*}xV_j^-                                                                                                    



    =&2V_j^*xV_j+2\sigma_{i/2}(V_j)x\sigma_{i/2}(V_j)^*
\end{align*}
for all $x\in B(H)$.

Note that $x\mapsto \sigma^\varphi_{i/2}(V_j)x\sigma^\varphi_{i/2}(V_j)^*$ is the KMS-adjoint of the map $x\mapsto V_j^*xV_j$ with respect to the state $\varphi$. As a result,
\begin{equation*}
    \sum_{j\in I}V_j^{+*}xV_j^++V_j^{-*}xV_j^-=4\Psi(x)
\end{equation*}
Therefore, we can assume without loss of generality that the operator $V_j$ satisfies $V_j=\sigma_{i/2}^\varphi(V_j)^*$ for every $j\in I$.

Let $x\in \rho^{1/4} B(H)\rho^{1/4}$. First, we calculate that
\begin{align*}
    \lVert\rho^{1/4}[\sigma^{\varphi}_{i/4}(V_j),x]\rho^{1/4}\rVert^2=&\mathrm{Tr}\left(\rho^{1/2}[\sigma^{\varphi}_{i/4}(V_j),x]^*\rho^{1/2}[\sigma^{\varphi}_{i/4}(V_j),x]\right)\\
    =&\mathrm{Tr}\big(\rho^{1/2}x^*\sigma^{\varphi}_{i/4}(V_j)^*\rho^{1/2}\sigma^{\varphi}_{i/4}(V_j)x+\rho^{1/2}\sigma^{\varphi}_{i/4}(V_j)^*x^*\rho^{1/2}x\sigma^{\varphi}_{i/4}(V_j)\\
    &-\rho^{1/2}\sigma^{\varphi}_{i/4}(V_j)^*x^*\rho^{1/2}\sigma^{\varphi}_{i/4}(V_j)x-\rho^{1/2}x^*\sigma^{\varphi}_{i/4}(V_j)^*\rho^{1/2}x\sigma^{\varphi}_{i/4}(V_j)\big)\\
    =&\mathrm{Tr}\big(\rho^{1/2}x^*\rho^{1/4}V_j^*V_j\rho^{1/4}x+\sigma^{\varphi}_{i/2}(V_j)\sigma^{\varphi}_{-i/2}(V_j^*)\rho^{1/4}x^*\rho^{1/2}x\rho^{1/4}\big)\\
    &-\rho^{1/2}V_j^*\rho^{-1/4}x^*\rho^{1/4}V_j\rho^{1/2}\rho^{-1/4}x\rho^{1/4}\\
    &-\rho^{1/2}\rho^{1/4}x^*\rho^{-1/4}\rho^{1/2}V_j^*\rho^{1/4}x\rho^{-1/4}V_j\big).
\end{align*}
Taking the sum over all $j\in I$ and using that $k^*+k=\sum_{j\in I}V_j^*V_j=\sum_{j\in I}\sigma^{\varphi}_{i/2}(V_j)\sigma^{\varphi}_{-i/2}(V_j^*)$, we find that
\begin{align*}
    \sum_{j\in I}\lVert\rho^{1/4}[\sigma^{\varphi}_{i/4}(V_j),x]\rho^{1/4}\rVert^2=&\mathrm{Tr}\big(\rho^{1/2}x^*\rho^{1/4}(k^*+k)\rho^{1/4}x+(k^*+k)\rho^{1/4}x^*\rho^{1/2}x\rho^{1/4}\big)\\
    &-\rho^{1/2}\Phi(\rho^{-1/4}x^*\rho^{1/4})\rho^{1/2}\rho^{-1/4}x\rho^{1/4}\\
    &-\rho^{1/2}\rho^{1/4}x^*\rho^{-1/4}\rho^{1/2}\Phi(\rho^{1/4}x\rho^{-1/4})\big)\\
    =&\mathrm{Tr}\left(\rho^{1/2}(k^*\rho^{-1/4}x^*\rho^{1/4}+\rho^{-1/4}x^*\rho^{1/4}k)\rho^{1/2}\rho^{-1/4}x\rho^{1/4}\right)\\
    &-\mathrm{Tr}\left(\rho^{1/2}\Phi(\rho^{-1/4}x^*\rho^{1/4})\rho^{1/2}\rho^{-1/4}x\rho^{1/4}\right)\\
    &+\mathrm{Tr}\left(\rho^{1/2}\rho^{1/4}x\rho^{-1/4}\rho^{1/2}(k^*\rho^{1/4}x\rho^{-1/4}+\rho^{1/4}x\rho^{-1/4}k)\right)\\
    &-\mathrm{Tr}\left(\rho^{1/2}\rho^{1/4}x^*\rho^{-1/4}\rho^{1/2}\Phi(\rho^{1/4}x\rho^{-1/4})\right)\\
    =&\mathrm{Tr}\left(\rho^{1/2}\mathcal L(\rho^{-1/4}x^*\rho^{1/4})\rho^{1/2}\rho^{-1/4}x\rho^{1/4}\right)\\
    &+\mathrm{Tr}\left(\rho^{1/2}\rho^{1/4}x^*\rho^{-1/4}\rho^{1/2}\mathcal L(\rho^{1/4}x\rho^{-1/4})\right).
\end{align*}

























Consequently, 
\begin{align*}
    \sum_{j\in I}\lVert\rho^{1/4}[\sigma^{\varphi}_{i/4}(V_j),\rho^{it}x\rho^{-it}]\rho^{1/4}\rVert^2=&\mathrm{Tr}\left(\rho^{1/2}\mathcal L(\rho^{-1/4+it}x^*\rho^{1/4-it})\rho^{1/2}\rho^{-1/4+it}x\rho^{1/4-it}\right)\\
    &+\mathrm{Tr}\left(\rho^{1/2}\rho^{1/4+it}x^*\rho^{-1/4-it}\rho^{1/2}\mathcal L(\rho^{1/4+it}x\rho^{-1/4-it})\right).
\end{align*}

By the KMS-symmetry of $\mathcal L$ and Lemma \ref{lem:appl_residue_thm}, this implies that
\begin{align*}
	&\int_{\mathbb R}\sum_{j\in I}\lVertV_j \rho^{it+1/4}x\rho^{-it+1/4}-\rho^{it+1/4}x\rho^{-it+1/4}V_j^\ast\rVert_2^2\frac{2\,dt}{\cosh 2\pi t}\\
    &\qquad=\int_{\mathbb R}\sum_{j\in I}\lVert\rho^{1/4}[\sigma^{\varphi}_{i/4}(V_j),\rho^{it}x\rho^{-it}]\rho^{1/4}\rVert_2^2\frac{2\,dt}{\cosh 2\pi t}\\
    &\qquad=\mathrm{Tr}(\rho^{1/2}x^*\rho^{1/2}\mathcal L(x))\\
    &\qquad=\mathcal E(\rho^{1/4}x\rho^{1/4})
\end{align*}
for all $x\in \rho^{1/4}B(H)\rho^{1/4}$. Since $\rho^{1/2}B(H)\rho^{1/2}$ is dense in $S^2(H)$ and $\mathcal E$ is bounded, this settles the first implication.

For the converse, consider the Hilbert space $\mathcal H=L^2(\mathbb R,\mu;\bigoplus_{j\in I}S^2(H))$ with bimodule actions of $B(H)$ given by $(x\eta y)(t)=(\sigma^\varphi_t(x)\eta_j(t)\sigma^\varphi_t(y))_{j\in I}$ and $(\mathcal J \eta)(t)=(\eta_j(t)^\ast)_{j\in I}$, $(\mathcal V_s\eta)(t)=\eta(s+t)$. One can check directly that $(\mathcal H,\mathcal J)$ is a self-dual $B(H)$-$B(H)$ correspondence and $\mathcal V_s$ satisfies $\mathcal V_s\mathcal J=\mathcal J \mathcal V_s$ and $\mathcal V_s(x\eta y)=\sigma^\varphi_s(x)(\mathcal V_s\eta)\sigma^\varphi_s(y)$.

Let 
\begin{equation*}
    \delta\colon S^2(H)\to \mathcal H,\,(\delta A)(t)=(V_j \rho^{it}A\rho^{-it}-\rho^{it}A\rho^{-it}V_j^\ast)_{j\in I}.
\end{equation*}
Since $\sum_j V_j^\ast V_j$ converges in strong operator topology, we have
\begin{align*}
    \int_{\mathbb R}\sum_{j}\lVertV_j \rho^{it}A\rho^{-it}-\rho^{it}A\rho^{-it}V_j^\ast\rVert_2^2\frac{2\,dt}{\cosh 2\pi t}\leq 4\left\lVert\sum_{j\in I} V_j^\ast V_j\right\rVert\lVertA\rVert_2^2,
\end{align*}
so that $\delta$ does indeed take values in $\mathcal H$ and is bounded. It is easy to see that $\delta\circ \Delta_\varphi^{is}=\mathcal V_s\circ\delta$ and $\delta\circ J=\mathcal J\circ \delta$. Finally, if $x,y\in B(H)$ and $t\in \mathbb R$, then
\begin{align*}
    \delta(x\rho^{1/2}y)(t)&=(V_j\sigma^\varphi_t(x)\rho^{1/2}\sigma^\varphi_t(y)-\sigma^\varphi_t(x)\rho^{1/2}\sigma^\varphi_t(y) V_j^\ast)_{j\in I}\\
    &=((V_j \Delta_\varphi^{it}x\rho^{1/2}-(\Delta_\varphi^{it}x\rho^{1/2})V_j^\ast)y+\sigma^\varphi_t(x)\rho^{1/2}(V_j^\ast \sigma^\varphi_t(y)-\sigma^\varphi_t(y)V_j^\ast))_{j\in I}\\
    &=(\delta(x\rho^{1/2})y)(t)+(\sigma^\varphi_t(x) (V_j \Delta_\varphi^{it}\rho^{1/2}y-(\Delta_\varphi^{it}\rho^{1/2}y)V_j))_{j\in I}\\
    &=(\delta(x\rho^{1/2})y)(t)+(x\delta(\rho^{1/2}y))(t).
\end{align*}
Now it follows from \Cref{thm:char_bdd} that
\begin{equation*}
    \mathcal E(A)=\sum_{j\in I}\int_\mathbb R\lVertV_j\rho^{it}A\rho^{-it}-\rho^{it}A \rho^{-it}V_j^\ast\rVert_2^2\frac{2\,dt}{\cosh 2\pi t},\quad A\in S^2(H),
\end{equation*}
defines a quantum Dirichlet form.

First assume that $\mathcal E$ is bounded and $a\in M\Omega\cap M^\prime\Omega$. By \Cref{thm:int_rep_form}, there exists an $M$-$M$ correspondence $\mathcal H$ and a linear map $\delta\colon M\Omega\cap M^\prime\Omega\to \mathcal H$ such that 
    \begin{equation*}
        \mathcal E(\Delta_\varphi^{it}a)=\int_{\mathbb R}\lVert\delta(\Delta_\varphi^{i(s+t)}a)\rVert_{\mathcal H}^2\frac{2\,ds}{\cosh2\pi s}.
    \end{equation*}
    Since $\frac{\cosh 2\pi s}{\cosh 2\pi(s-t)}\in [e^{-2\pi\lvertt\rvert},e^{2\pi\lvertt\rvert}]$ for all $s,t\in \mathbb R$, we have
    \begin{align*}
        \mathcal E(\Delta_\varphi^{it}a)&=\int_\mathbb R\lVert\delta(\Delta_\varphi^{is}a)\rVert_{\mathcal H}^2\frac{2\,ds}{\cosh 2\pi(s-t)}\\
        &\leq e^{2\pi\lvertt\rvert}\int_{\mathbb R}\lVert\delta(\Delta_\varphi^{is}a)\rVert_{\mathcal H}^2\frac{2\,ds}{\cosh 2\pi s}\\
        &=e^{2\pi\lvertt\rvert}\mathcal E(a).
    \end{align*}
    The result for general $a\in L^2(M)$ follows since $M\Omega\cap M^\prime \Omega$ is dense in $L^2(M)$ and $\mathcal E$ is bounded.

    Now if $\mathcal E$ is not necessarily bounded, we can use that the Moreau regularization $\mathcal E^{(\varepsilon)}$ is a bounded completely Dirichlet form for all $\varepsilon>0$ to obtain
    \begin{equation*}
        \mathcal E(\Delta_\varphi^{it} a)=\sup_{\varepsilon>0}\mathcal E_\varepsilon(\Delta_\varphi^{it}a)\leq e^{2\pi\lvertt\rvert}\sup_{\varepsilon>0}\mathcal E_\varepsilon(a)=e^{2\pi \lvertt\rvert}\mathcal E(a)
    \end{equation*}
    for all $a\in L^2(M)$ and $t\in\mathbb R$.

If $a\in L^2(M)$ and $Ja=a$, let $a_n$ be the projection onto the closed convex subset $\{b\in L^2(M)\mid Jb=b,\,n\Omega_\varphi\pm b\in L^2_+(M)\}\subset \Delta_\varphi^{1/4}M\Omega_\varphi$. We have $a_n\to a$ in $L^2(M)$ and $\mathcal E(a_n)\leq \mathcal E(a)$ by the Dirichlet form property \cite[Proposition 4.5]{Cip97}. It follows that every subnet of $(a_n)$ has a subnet that converges weakly to $a$ in $(\operatorname{dom}(\mathcal E),\lVert\cdot\rVert_{\mathcal E})$, hence $(a_n)$ itself converges weakly to $a$ in $(\operatorname{dom}(\mathcal E),\lVert\cdot\rVert_{\mathcal E})$. Together with $\limsup_{n\to\infty}\lVerta_n\rVert_{\mathcal E}\leq \lVerta\rVert_{\mathcal E}$, this implies $\lVerta-a_n\rVert_{\mathcal E}\to 0$.

    Since $\operatorname{dom}(\mathcal E)$ is invariant under $J$, it suffices therefore to show that for every $a\in\operatorname{dom}(\mathcal E)\cap \Delta_\varphi^{1/4}M\Omega_\varphi$ there exists a sequence $(a_n)$ in $\mathfrak A_{\mathcal E}$ such that $a_n\to a$ in form norm.

    Let $x\in M$ such that $a=\Delta_\varphi^{1/4}x\Omega_\varphi\in\operatorname{dom}(\mathcal E)$ and let $ x_n=\sqrt{\frac n\pi}\int_{\mathbb R}e^{-nt^2}\sigma^\varphi_t(x)\,dt$. It follows from the proof of \cite[Lemma 1.3]{Haa75} that $x_n$ is analytic for $\sigma^\varphi$ and $x_n\Omega_\varphi\to x\Omega_\varphi$, $x_n^\ast \Omega_\varphi\to x^\ast\Omega_\varphi$. By Young's inequality, we obtain
    \begin{align*}
        \lVert\Delta_\varphi^{1/4}(x-x_n)\Omega_\varphi\rVert^2
        &=\langle (x-x_n)\Omega_\varphi,\Delta_\varphi^{1/2}(x-x_n)\Omega_\varphi\rangle\\
        &\leq \frac 1 2\lVert(x-x_n)\Omega_\varphi\rVert^2+\frac 1 2\lVert\Delta_\varphi^{1/2}(x-x_n)\Omega_\varphi\rVert^2\\
        &=\frac 1 2\lVert(x-x_n)\Omega_\varphi\rVert^2+\frac 1 2\lVert(x^\ast-x_n^\ast)\Omega_\varphi\rVert^2\\
        &\to 0.
    \end{align*}

    Let $V_t=\Delta_\varphi^{it}|_{\operatorname{dom}(\mathcal E)}$. By \Cref{lem:res_mod_group_form}, the family $(V_t)_{t\in\mathbb R}$ is a strongly continuous group on $(\operatorname{dom}(\mathcal E),\lVert\cdot\rVert_{\mathcal E})$. We have
    \begin{equation*}
        \Delta_\varphi^{1/4}x_n\Omega_\varphi=\sqrt\frac n\pi\int_\mathbb R e^{-nt^2}V_t(\Delta_\varphi^{1/4}x\Omega_\varphi)\,dt\in \bigcap_{z\in\mathbb C}\operatorname{dom}(V_z)
    \end{equation*}
    by \Cref{lem:Haagerup_approx_groups}. Thus $\Delta_\varphi^{1/4}x_n\Omega_\varphi=\sigma_{-i/4}^\varphi(x_n)\Omega_\varphi\in \mathfrak A_{\mathcal E}$. Finally,
    \begin{align*}
        \lVert\Delta_\varphi^{1/4}x\Omega_\varphi-\Delta_\varphi^{1/4}x_n\Omega_\varphi\rVert_{\mathcal E}
        &\leq \sqrt\frac n\pi\int_{\mathbb R}e^{-nt^2}\lVertV_t\Delta_\varphi^{1/4}x\Omega_\varphi-\Delta_\varphi^{1/4}x\Omega_\varphi\rVert_{\mathcal E}\,dt\\
        &=\frac 1{\sqrt \pi}\int_\mathbb R e^{-s^2}\lVertV_{s/\sqrt n}\Delta_\varphi^{1/4}x\Omega_\varphi-\Delta_\varphi^{1/4}x\Omega_\varphi\rVert_{\mathcal E}\,ds\\
        &\to 0
    \end{align*}
    by the dominated convergence theorem.

By \Cref{prop:Tomita_form_dense}, the set $\mathfrak A_{\mathcal E}$ is dense in $(\operatorname{dom}(\mathcal E),\lVert\cdot\rVert_{\mathcal E})$ and by definition it is contained in $\operatorname{dom}(V_{-i/2})$. It follows from \Cref{lem:core_analytic_generator} that it is a core for $V_{-i/2}$.

    It is clear from the definition that $V_{-i/2}\subset \Delta_\varphi^{1/2}$. Since $\langle a,\Delta_\varphi^{1/2}a\rangle_2\geq 0$ for all $a\in \operatorname{dom}(\Delta_\varphi^{1/2})$, it suffices to show that $\operatorname{Re}\mathcal E(a,V_{-i/2}a)\geq 0$ for all $a\in\mathfrak A_{\mathcal E}$. By polarization, $\mathcal E^{(\varepsilon)}(b,c)\to \mathcal E(b,c)$ for all $b,c\in\operatorname{dom}(\mathcal E)$. Therefore we can assume that $\mathcal E$ is bounded.

    Let $(\mathcal H,\mathcal J,(\mathcal V_s)_{s\in\mathbb R},\delta)$ as in \Cref{thm:char_bdd}. By \cite[Theorem 4.2]{Uit00}, we have
    \begin{equation*}
        V_{-i/2}a=\lim_{n\to\infty}\sqrt\frac n\pi\int_{\mathbb R}e^{-n(s+i/2)^2}\Delta_\varphi^{is}a\,ds.
    \end{equation*}
    Since $\delta$ is bounded, this implies
    \begin{equation*}
        \delta(V_{-i/2}a)=\lim_{n\to\infty}\sqrt\frac n\pi\int_{\mathbb R}e^{-n(s+i/2)^2}\mathcal V_s\delta(a)\,ds,
    \end{equation*}
    which equals $\mathcal V_{-i/2}\delta(a)$ by another application of \cite[Theorem 4.2]{Uit00}.

    Thus $\operatorname{Re}\mathcal E(a,V_{-i/2}a)=\operatorname{Re}\langle \delta(a),\mathcal V_{-i/2}\delta(a)\rangle$, which is positive since $\mathcal V_{-i/2}$ is accretive.

If $\mathcal E$ is a quantum Dirichlet form and $a\in \operatorname{dom}(\mathcal E)\cap M\Omega_\varphi$, $b\in \operatorname{dom}(\mathcal E)\cap M^\prime \Omega_\varphi$, then $ab\in \operatorname{dom}(\mathcal E)$ and
    \begin{equation*}
        \mathcal E(ab)^{1/2}\leq \lVert\pi_l(a)\rVert\mathcal E(b)^{1/2}+\mathcal E(a)^{1/2}\lVert\pi_r(b)\rVert.
    \end{equation*}

First assume that $\mathcal E$ is bounded. By \Cref{thm:char_bdd} there exists an $M$-$M$ correspondence $\mathcal H$ and a bounded linear map $\delta\colon L^2(M)\to\mathcal H$ such that $\delta(ab)=\pi_l(a)\cdot\delta(b)+\delta(a)\cdot J \pi_r(b)^\ast J$ and $\mathcal E(c)=\lVert\delta(c)\rVert^2$ for all $c\in L^2(M)$. Thus
    \begin{align*}
        \mathcal E(ab)^{1/2}
        &=\lVert\delta(ab)\rVert\\
        &=\lVert\pi_l(a)\delta(b)+\delta(a)\cdot J \pi_r(b)^\ast J\rVert\\
        &\leq \lVert\pi_l(a)\rVert\mathcal E(b)^{1/2}+\mathcal E(a)^{1/2}\lVert\pi_r(b)\rVert.
    \end{align*}
    For not necessarily bounded forms, the result follows now easily using the approximation by the Moreau regularization as before.

If $a\in\mathfrak A_{\mathcal E}$, then
\begin{equation*}
    \lVert\delta(a)\rVert^2=\lim_{n\to\omega}\lVert\delta^{(n)}(a)\rVert^2=\lim_{n\to\omega}\mathcal E_{1/n}(a)=\mathcal E(a).
\end{equation*}
As $\mathfrak A_{\mathcal E}$ is a form core for $\mathcal E$ by \Cref{prop:Tomita_form_dense}, the remaining claims follow from standard operator-theoretic arguments.

Since $\lVert\mathcal V_s\rVert\leq e^{\pi\lverts\rvert}$, by \cite[Theorem I.5.8]{EN00} it suffices to show that $\mathcal V_s$ is weakly continuous on the total subset $\{x\delta(a)y\mid a\in \mathfrak A_{\mathcal E},\,x,y\in A_{\mathcal E}\}$ of $\mathcal H$. Since $\mathcal V_s(x\delta(a)y)=\sigma^\varphi_s(x)\delta(\Delta_\varphi^{is}a)\sigma^\varphi_s(y)$ and $\sigma^\varphi_s(x)\to x$, $\sigma^\varphi_s(y)\to y$ in strong operator topology as $s\to 0$, it is enough to show that $\delta(\Delta_\varphi^{is}a)\to \delta(a)$ weakly as $s\to 0$.

    We have $\lVert\delta(\Delta_\varphi^{is}a)\rVert=\mathcal E(\Delta_\varphi^{is}a)^{1/2}\leq e^{\pi\lverts\rvert}\lVert\delta(a)\rVert$ by \Cref{lem:bound_mod_grp_form}. Let $L$ be the positive self-adjoint operator associated with $\mathcal E$. If $b\in \operatorname{dom}(L)$, then it follows from \Cref{lem:deriv_unbdd} that
\begin{equation*}
    \langle \delta(\Delta_\varphi^{is}a),\overline\delta(b)\rangle=\langle \Delta_\varphi^{is}a,L(b)\rangle\to \langle a,L(b)\rangle=\langle \delta(a),\overline\delta(b)\rangle\quad \text{as }s\to 0.
\end{equation*}
Since $\operatorname{dom}(L)$ is dense in $\operatorname{dom}(\mathcal E)$ with respect to $\lVert\cdot\rVert_{\mathcal E}$ by the spectral theorem, $\overline\delta(\operatorname{dom}(L))$ is dense in $\overline{\delta(\mathfrak A_{\mathcal E})}$. We conclude that $\delta(\Delta_\varphi^{is}a)\to \delta(a)$ weakly as $s\to 0$.

From the properties of $(\mathcal V_t)_{t\in\mathbb R}$, it follows that $\mathcal V_t(\pi_l(a)\cdot\delta(b))=\pi_l(\Delta_\varphi^{it}a)\cdot\delta(\Delta_\varphi^{it}b)$ for $t\in\mathbb R$. Hence it suffices to prove that $z\mapsto \pi_l(\Delta_\varphi^{iz}a)\cdot\delta(\Delta_\varphi^{iz}b)$ is entire analytic. By definition of $\mathfrak A_{\mathcal E}$, we have $\pi_l(a)\in \operatorname{dom}(\sigma^\varphi_z)$ and $\sigma^\varphi_z(\pi_l(a))=\pi_l(\Delta_\varphi^{iz}a)$ for $z\in \mathbb C$. Moreover, the map $z\mapsto \sigma^\varphi_z(\pi_l(a))$ is entire analytic. By the product rule, it is therefore enough to show that $z\mapsto \delta(\Delta_\varphi^{iz}b)$ is entire analytic.

    By definition of $\mathfrak A_{\mathcal E}$, the map $F\colon \mathbb C\to\operatorname{dom}(\mathcal E),\,z\mapsto \Delta_\varphi^{iz}b$ is analytic with respect to $\lVert\cdot\rVert_{\mathcal E}$. Hence
    \begin{equation*}
        \left\lVert\frac 1 h\big(\delta(F(z+h)-\delta(F(z))\big)-\overline\delta(F^\prime(z))\right\rVert_{\mathcal H}^2=\mathcal E\left(\frac 1 h(F(z+h)-F(z))-F^\prime(z)\right)\to 0
    \end{equation*}
    as $h\to 0$. Therefore, $z\mapsto \delta(\Delta_\varphi^{iz}b)$ is entire analytic.

\label{thm:char_unbdd}
    If $\mathcal E$ is a quantum Dirichlet form, then there exist
    \begin{itemize}
        \item a Hilbert bimodule $\mathcal H$ over $A_{\mathcal E}$,
        \item an anti-unitary involution $\mathcal J\colon\mathcal H\to\mathcal H$,
        \item a strongly continuous one-parameter group $(\mathcal V_s)_{s\in\mathbb R}$ on $\mathcal H$ with $\mathcal V_{-i/2}$ accretive,
        \item a closable operator $\delta\colon \mathfrak A_{\mathcal E}\to\mathcal H$
    \end{itemize}
    satisfying
    \begin{enumerate}[(i)]
        \item $\mathcal H=\overline{\operatorname{span}}\{x\delta(a)y\mid a\in \mathfrak A_{\mathcal E},\,x,y\in A_{\mathcal E}\}$,
        \item $\mathcal J(x\eta y)=y^\ast (\mathcal J\eta)x^\ast$, $\mathcal V_s(x\eta y)=\sigma^\varphi_s(x)(\mathcal V_s\eta)\sigma^\varphi_s(y)$ for all $x,y\in A_{\mathcal E}$, $\eta\in\mathcal H$, $s\in\mathbb R$,
        \item $\mathcal V_s\mathcal J=\mathcal J \mathcal V_s$ for all $s\in\mathbb R$,
        \item $\delta\circ J=\mathcal J\circ\delta$, $\delta\circ \Delta_\varphi^{is}=\mathcal V_s\circ\delta$ for all $s\in\mathbb R$,
        \item $\delta(ab)=\pi_l(a)\delta(b)+\delta(a)\cdot J \pi_r(b)^\ast J$ for all $a,b\in\mathfrak A_{\mathcal E}$
    \end{enumerate}
    such that
    \begin{equation*}
        \operatorname{dom}(\mathcal E)=\operatorname{dom}(\overline\delta),\,\mathcal E(a)=\lVert\overline\delta(a)\rVert_{\mathcal H}^2,\quad a\in\operatorname{dom}(\mathcal E).
    \end{equation*}

Let $(\mathcal H,\mathcal J)$ be a self-dual $M$-$M$ correspondence and $(\mathcal V_s)_{s\in\mathbb R}$ a strongly continuous group on $\mathcal H$ such that $\mathcal V_s\mathcal J=\mathcal J\mathcal V_s$ for all $s\in \mathbb R$ and $\mathcal V_s(x\eta y)=\sigma^\varphi_s(x)(\mathcal V_s\eta)\sigma^\varphi_s(y)$ for all $x,y\in M$, $\eta\in\mathcal H$ and $s\in\mathbb R$. For $s\in\mathbb R$, if $\mathcal V_s=\tilde{\mathcal U_s}\lvert\mathcal V_s\rvert$ is the polar decomposition of $\mathcal V_s$, then $\lvert\mathcal V_s\rvert$ is a bimodule map, $\tilde{\mathcal U_s}$ is unitary and
    \begin{equation*}
        \tilde{\mathcal U_s}(x\eta y)=\sigma_s(x)(\tilde{\mathcal U}_s\eta)\sigma_s(y)
    \end{equation*}
    for all $x,y\in A_{\mathcal E}$, $\eta\in\mathcal H$.

By definition of a strongly continuous group, $\mathcal V_s$ is invertible. Thus the partial isometry $\tilde{\mathcal U}_s$ in the polar decomposition is unitary. Note that
    \begin{align*}
    \mathcal V_s^\ast\mathcal V_s\pi_l^\mathcal H(x)\pi_r^\mathcal H(y)&
    =\mathcal V_s^\ast \pi_l^\mathcal H(\sigma_s(x))\pi_r^\mathcal H(\sigma^\varphi_s(y))\mathcal V_s\\
    &=(\pi_l^\mathcal H(\sigma_s(x^\ast))\pi_r^\mathcal H(\sigma_s(y^\ast)) \mathcal V_s)^\ast\mathcal V_s\\
    &=(\mathcal V_s \pi_l^{\mathcal H}(x^\ast)\pi_r^\mathcal H(y^\ast))^\ast\mathcal V_s\\
    &=\pi_l^\mathcal H(x)\pi_r^\mathcal H(y)\mathcal V_s^\ast\mathcal V_s
    \end{align*}
    for all $x,y\in M$. Therefore $\lvert\mathcal V_s\rvert$ is a bimodule map and
\begin{equation*}
    \tilde{\mathcal U}_s(x\eta y)=\mathcal V_s\lvert\mathcal V_s\rvert^{-1}(x\eta y)=\mathcal V_s(x(\lvert\mathcal V_s\rvert^{-1}\eta)y)=\sigma_s(x)(\tilde{\mathcal U}_s\xi)\sigma_s(y)
\end{equation*}
for all $x,y\in A_{\mathcal E}$ and $\eta\in\mathcal H$.

\label{prop:deform_unitary_group}
    Let $\mu$ be the measure on $\mathbb R$ with density $\frac{d\mu}{dt}=\frac{2}{\cosh 2\pi t}$, let $(\tilde\mathcal H,\tilde \mathcal J)$ be a self-dual $M$-$M$ correspondence and let $\mathcal H=L^2(\mathbb R,\mu;\tilde\mathcal H)$. Define the structure of an $M$-$M$ correspondence on $\mathcal H$ by $(x\eta y)(t)=\sigma^\varphi_t(x)\eta(t)\sigma^\varphi_t(y)$ and an anti-unitary involution $\mathcal J\colon \mathcal H\to \mathcal H$ by $(\mathcal J\eta)(t)=\tilde\mathcal J\eta(t)$. For $s\in\mathbb R$ let
    \begin{equation*}
        \mathcal V_s\colon \mathcal H\to \mathcal H,\,(V_s \xi)(t)=\xi(s+t).
    \end{equation*}
    If $\mathcal V_s=\tilde{\mathcal U}_s\lvert\mathcal V_s\rvert$ is the polar decomposition of $\mathcal V_s$ for $s\in\mathbb R$, then there exists a strongly continuous unitary group $(\mathcal U_s)_{s\in\mathbb R}$ on $\mathcal H$ such that $\tilde{\mathcal U}_{s/n}^n\to \mathcal U_s$ as $n\to\infty$ in strong operator toplogy for all $s\in \mathbb R$. The difference of the generators of $(\mathcal V_s)_{s\in\mathbb R}$ and $(\tilde{\mathcal U}_s)_{s\in\mathbb R}$ is a bounded bimodule map. Moreover, $(\mathcal H,\mathcal J,(\mathcal U_s)_{s\in\mathbb R})$ is a Tomita correspondence.

Let us first compute $\mathcal V_s^\ast$ explicitly. For this purpose, we write $V(t)=-\log \frac 2{\cosh 2\pi t}$. For $\xi,\eta\in L^2(\mathbb R,\mu;\tilde\mathcal H)$ we have
\begin{align*}
    \langle \mathcal V_s\xi,\mathcal V_s\eta\rangle
    &=\int_{\mathbb R} \langle \xi(s+t),\eta(s+t)\rangle e^{-V(t)}\,dt\\
    &=\int_\mathbb R \langle \xi(t),\eta(t)\rangle e^{V(t)-V(t-s)}e^{-V(t)}\,dt.
\end{align*}
Thus $\mathcal V_s^\ast \mathcal V_s \xi(t)=e^{V(t)-V(t-s)}\xi(t)$ and $\tilde{\mathcal U}_s\xi(t)=(\mathcal V_s^\ast\mathcal V_s)^{-1/2}\xi(s+t)=e^{-\frac 1 2(V(s+t)-V(t))}\xi(s+t)$.

We note that
\begin{align*}
    \frac 1 s(\mathcal V_s\xi-\tilde{\mathcal U}_s\xi)(t)=\frac 1 s(1-e^{-\frac 1 2(V(s+t)-V(t))})\xi(s+t)=\frac 1 s(1-e^{-\frac 1 2(V(s+t)-V(t))})\mathcal V_s \xi(t).
\end{align*}
For $x\in [-1,1]\setminus \{0\}$ and $y\in [-1,1]$ let 
\begin{equation*}
    F(x,y)=\frac 1 x\left(1-\left(\frac{1+y}2 e^x+\frac {1-y}2 e^{-x}\right)^{-1/2}\right)
\end{equation*}
and note that $2\pi F(2\pi s,\tanh 2\pi t)=\frac 1 s(1-e^{-\frac 1 2(V(s+t)-V(t))})$.

We have $\frac{1+y}2 e^x+\frac {1-y}2 e^{-x}=1+xy+O(x^2)$ as $x\to 0$ uniformly in $y\in [-1,1]$ and $\left(\frac{1+y}2 e^x+\frac {1-y}2 e^{-x}\right)^{-1/2}=1-\frac{xy}2+O(x^2)$ as $x\to 0$ uniformly in $y\in [-1,1]$, thus $F(x_n,y_n)\to \frac{y}2$ as $x_n\to 0$ and $y_n\to y$. Therefore, $F$ extends to a continuous function on $[-1,1]^2$. In particular, it is bounded.

Hence, if $\xi\in L^2(\mathbb R,\mu;\tilde\mathcal H)$, then
\begin{align*}
    \int_\mathbb R\left\lVert \frac 1 s(1-e^{-\frac 1 2(V(s+t)-V(t))})\xi(t)-\pi\tanh (2\pi t)\xi(t)\right\rVert^2\,d\mu(t)\to 0
\end{align*}
as $s\to 0$ by the dominated convergence theorem.

Together with the strong convergence $\mathcal V_s\to \mathrm{id}$ we get
\begin{equation*}
    \frac 1 s(\mathcal V_s\xi-\tilde{\mathcal U}_s\xi)\to B \xi,
    \end{equation*}
where $B\xi(t)=\frac 1 2 V^\prime(t)\xi(t)$. As $V^\prime\in L^\infty(\mathbb R)$, this implies that whenever $\xi$ belongs to the domain of the generator $A$ of $(\mathcal V_s)$, then
\begin{equation*}
    \frac 1 s(\tilde{\mathcal U}_s\xi-\xi)=\frac 1 s(\tilde{\mathcal U}_s \xi-\mathcal V_s\xi)+\frac  1s(\mathcal V_s\xi-\xi)\to \frac 1 2 V'\xi+A\xi.
\end{equation*}
Since $\pm (A+B)$ is a bounded perturbation of the semigroup generator $\pm A$, it follows that $A+B$ generates a strongly continuous group $(\mathcal U_s)$ on $L^2(\mathbb R,\mu;\tilde\mathcal H)$ and by Chernoff's theorem \cite[Theorem III.5.2]{EN00}, we have
\begin{equation*}
    \mathcal U_s\xi=\lim_{n\to\infty}\tilde{\mathcal U}_{s/n}^n\xi
\end{equation*}
for all $\xi\in L^2(\mathbb R,\mu;\tilde\mathcal H)$ and $s\geq 0$. Moreover, since $-(A+B)$ also generates a semigroup, we see that $\mathcal U_s$ is invertible for every $s\geq 0$ and we can extend $(\mathcal U_s)$ to a strongly continuous group by defining $\mathcal U_{-s}=\mathcal U_s^{-1}$ for $s\geq 0$. Moreover, as a strong limit of unitary operators, $\mathcal U_s$ is an isometry for every $s\in\mathbb R$.

The groups $(\mathcal U_s)$ and $(\mathcal V_s)$ are related by the following identity \cite[Corollary III.1.7]{EN00}:
\begin{equation*}
    \mathcal U_s\xi=\mathcal V_s\xi+\int_0^s \mathcal V_{s-r}B\mathcal U_r\xi\,dr.
\end{equation*}
It follows that
\begin{align*}
    \lVert\mathcal U_s\xi-\mathcal V_s\xi\rVert\leq \lverts\rvert\pi e^{\pi\lverts\rvert}\lVert\xi\rVert.
\end{align*}

From $\tilde{\mathcal U}_s(x\xi y)=\sigma_s(x)(\tilde{\mathcal U}_s\xi)\sigma_s(y)$ it is easy to deduce $\mathcal U_s(x\xi y)=\sigma_s(x)(\mathcal U_s \xi)\sigma_s(y)$. Furthermore, since $\mathcal V_s$ commutes with $\mathcal J$ and $\mathcal J$ is self-adjoint, $\mathcal U_s$ also commutes with $\mathcal J$. Therefore, $(L^2(\mathbb R,\mu;\tilde\mathcal H),\mathcal J,(\mathcal U_s)_{s\in\mathbb R})$ is a Tomita correspondence.

\label{thm:Tomita_corr_Dir_form}
    If $\mathcal E$ is a bounded quantum Dirichlet form, then there exists a von Neumann algebra $\hat M\supset M$ with a faithful normal conditional expectation $E\colon \hat M\to M$, a bounded self-adjoint $M$-bimodule map $B\colon L^2(\hat M)\to L^2(\hat M)$ and a bounded linear map $\delta\colon L^2(M)\to L^2(\hat M)$ satisfying
    \begin{itemize}
        \item $J_{\varphi\circ E}\circ\delta=\delta\circ J_\varphi$
        \item $e^{s(i\log\Delta_{\varphi\circ E}+B)}\circ \delta=\delta\circ \Delta_\varphi^{is}$, where $(e^{s(i\log\Delta_{\varphi\circ E}+B)})_{s\in\mathbb R}$ is the group generated by $i\log\Delta_{\varphi\circ E}-B$,
        \item $\delta(ab)=\pi_l(a)\delta(b)+\delta(a)\cdot J_{\hat M}\pi_r(b)^\ast J_{\hat M}$ for all $a,b\in\mathfrak A_{\mathcal E}$
        \end{itemize}
    such that
    \begin{equation*}
        \mathcal E(a)=\lVert\delta(a)\rVert_{L^2(\hat M)}^2,\quad a\in L^2(M).
    \end{equation*}
